+/**
+ * ContactForm — React-style component logic rendered into the DOM.
+ * Validation messages are suppressed on initial render; they only appear
+ * after the user has interacted with (blurred) a field or attempted submit.
+ */
+
+(function () {
+  "use strict";
+
+  const PHONE_REGEX = /^\+?[\d\s\-().]{7,20}$/;
+  const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+  // ---------- state ----------
+  const state = {
+    values: { fullName: "", email: "", phone: "" },
+    touched: { fullName: false, email: false, phone: false },
+    submitted: false,
+  };
+
+  // ---------- validation ----------
+  function validate(values) {
+    const errors = {};
+    if (!values.fullName.trim()) {
+      errors.fullName = "Full name is required.";
+    }
+    if (!values.email.trim()) {
+      errors.email = "Email address is required.";
+    } else if (!EMAIL_REGEX.test(values.email.trim())) {
+      errors.email = "Please enter a valid email address.";
+    }
+    if (values.phone.trim() && !PHONE_REGEX.test(values.phone.trim())) {
+      errors.phone = "Phone number format is not recognised. See the hint below.";
+    }
+    return errors;
+  }
+
+  // ---------- DOM helpers ----------
+  function getField(name) {
+    return document.getElementById(`field-${name}`);
+  }
+
+  function showError(name, message) {
+    const field = getField(name);
+    const input = field.querySelector("input");
+    let errEl = field.querySelector(".error-message");
+
+    if (!errEl) {
+      errEl = document.createElement("span");
+      errEl.className = "error-message";
+      errEl.setAttribute("role", "alert");
+      errEl.id = `error-${name}`;
+      // Insert after the input (before any helper text)
+      const helperText = field.querySelector(".helper-text");
+      if (helperText) {
+        field.insertBefore(errEl, helperText);
+      } else {
+        field.appendChild(errEl);
+      }
+    }
+
+    errEl.innerHTML = `
+      <svg class="icon" xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24"
+           fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"
+           aria-hidden="true">
+        <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
+      </svg>
+      ${message}`;
+
+    input.classList.add("input-error");
+    input.setAttribute("aria-describedby",
+      [input.getAttribute("aria-describedby") || "", `error-${name}`]
+        .join(" ").trim()
+    );
+    input.setAttribute("aria-invalid", "true");
+  }
+
+  function clearError(name) {
+    const field = getField(name);
+    const input = field.querySelector("input");
+    const errEl = field.querySelector(".error-message");
+    if (errEl) errEl.remove();
+    input.classList.remove("input-error");
+    input.removeAttribute("aria-invalid");
+
+    // Restore original aria-describedby (helper text id only)
+    const helperId = `helper-${name}`;
+    const helperEl = document.getElementById(helperId);
+    if (helperEl) {
+      input.setAttribute("aria-describedby", helperId);
+    } else {
+      input.removeAttribute("aria-describedby");
+    }
+  }
+
+  function renderFieldErrors(errors) {
+    ["fullName", "email", "phone"].forEach((name) => {
+      const shouldShow = state.submitted || state.touched[name];
+      if (shouldShow && errors[name]) {
+        showError(name, errors[name]);
+      } else {
+        clearError(name);
+      }
+    });
+  }
+
+  // ---------- event wiring ----------
+  function init() {
+    const form = document.getElementById("contact-form");
+
+    ["fullName", "email", "phone"].forEach((name) => {
+      const input = document.getElementById(name);
+
+      input.addEventListener("input", () => {
+        state.values[name] = input.value;
+        if (state.touched[name] || state.submitted) {
+          renderFieldErrors(validate(state.values));
+        }
+      });
+
+      input.addEventListener("blur", () => {
+        state.touched[name] = true;
+        renderFieldErrors(validate(state.values));
+      });
+    });
+
+    form.addEventListener("submit", (e) => {
+      e.preventDefault();
+      state.submitted = true;
+
+      const errors = validate(state.values);
+      renderFieldErrors(errors);
+
+      if (Object.keys(errors).length > 0) {
+        // Focus first invalid field
+        const firstErrorName = ["fullName", "email", "phone"].find(
+          (n) => errors[n]
+        );
+        if (firstErrorName) {
+          document.getElementById(firstErrorName).focus();
+        }
+        return;
+      }
+
+      // Success
+      document.getElementById("success-banner").classList.add("visible");
+      form.reset();
+      state.values = { fullName: "", email: "", phone: "" };
+      state.touched = { fullName: false, email: false, phone: false };
+      state.submitted = false;
+      renderFieldErrors({});
+
+      document.getElementById("success-banner").scrollIntoView({
+        behavior: "smooth",
+        block: "nearest",
+      });
+    });
+  }
+
+  document.addEventListener("DOMContentLoaded", init);
+})();
+
